#include <stdio.h>

int n, m;
int adj[20];
long long count = 0;

void backtrack(int idx, int banned_mask) {
    if (idx == n) {
        count++;
        return;
    }

    // Opção 1: Não incluir o ingrediente idx
    backtrack(idx + 1, banned_mask);

    // Opção 2: Incluir o ingrediente idx (se for compatível)
    if (!(banned_mask & (1 << idx))) {
        backtrack(idx + 1, banned_mask | adj[idx]);
    }
}

int main() {
    if (scanf("%d %d", &n, &m) != 2) return 0;

    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        --u; --v;
        adj[u] |= (1 << v);
        adj[v] |= (1 << u);
    }

    backtrack(0, 0);

    // O conjunto vazio não é considerado um sanduíche válido
    printf("%lld\n", count - 1);

    return 0;
}
